def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    oppD_tail = 0
    for _, o in reversed(history):
        if o == 'D':
            oppD_tail += 1
        else:
            break

    oppC = 0
    myC = 0
    for m, o in history:
        if m == 'C':
            myC += 1
        if o == 'C':
            oppC += 1

    opp_rate = oppC / n

    rec_len = n if n < 20 else 20
    rec_start = n - rec_len
    rec_oppC = 0
    for i in range(rec_start, n):
        if history[i][1] == 'C':
            rec_oppC += 1
    rec_opp_rate = rec_oppC / rec_len

    total_forg = 0
    total_ret = 0
    recent_forg = 0
    recent_ret = 0
    recent_start = rec_start
    if recent_start < 1:
        recent_start = 1

    for i in range(1, n):
        if history[i-1][0] == 'D':
            if history[i][1] == 'C':
                total_forg += 1
                if i >= recent_start:
                    recent_forg += 1
            else:
                total_ret += 1
                if i >= recent_start:
                    recent_ret += 1

    hostile = (
        (oppC == 0 and n > 2) or
        (rec_opp_rate < 0.18 and n > 5) or
        (oppD_tail >= 6 and opp_rate < 0.50)
    )

    mode = False
    if last_opp == 'C' and recent_ret == 0 and rec_opp_rate >= 0.60 and opp_rate >= 0.55:
        if recent_forg >= 1:
            mode = True
        elif total_forg >= 3 and total_ret * 3 < total_forg:
            mode = True

    exploit = mode and myC * 100 > (n + 1) * 73

    if n == 98:
        if hostile:
            return 'D'
        if mode and myC * 10 > (n + 1) * 7:
            return 'D'
        return 'C'

    if exploit:
        return 'D'
    if mode:
        return 'C'

    if (
        myC == n and
        last_opp == 'C' and
        45 <= n <= 55 and
        rec_opp_rate >= 0.80 and
        opp_rate >= 0.70
    ):
        return 'D'

    if last_opp == 'D':
        if hostile or (rec_opp_rate < 0.25 and oppD_tail >= 3):
            return 'D'

        if last_me == 'C' and opp_rate > 0.70 and oppD_tail <= 4:
            return 'C'

        if last_me == 'D' and opp_rate > 0.70 and oppD_tail <= 3:
            return 'C'

        if opp_rate < 0.30:
            return 'D'

        if oppD_tail == 1 and rng.random() < 0.10 and opp_rate > 0.55:
            return 'C'

        return 'D'

    if hostile:
        return 'D'
    if rec_opp_rate < 0.35:
        return 'D'

    return 'C'
